export interface Codec<T> {
  readonly decode: (text: string) => T;
  readonly encode: (value: T) => string;
}

export class CodecBank {
  private readonly codecs = new Map<string, Codec<unknown>>();

  register<T>(name: string, codec: Codec<T>): void {
    if (name.trim().length === 0) throw new RangeError("Codec name must not be blank");
    if (this.codecs.has(name)) throw new Error(`Duplicate codec: ${name}`);
    this.codecs.set(name, codec as Codec<unknown>);
  }

  decode<T>(name: string, text: string): T {
    const codec = this.codecs.get(name);
    if (codec === undefined) throw new Error(`Unknown codec: ${name}`);
    return codec.decode(text) as T;
  }

  encode<T>(name: string, value: T): string {
    const codec = this.codecs.get(name);
    if (codec === undefined) throw new Error(`Unknown codec: ${name}`);
    return codec.encode(value);
  }

  names(): string[] {
    return [...this.codecs.keys()];
  }
}

