    decode(text) {
      if (!/^-?(0|[1-9][0-9]*)$/.test(text)) throw new RangeError("Invalid integer");
      const value = Number(text);
      if (!Number.isSafeInteger(value)) throw new RangeError("Unsafe integer");
      return value;
