    encode(value) {
      if (!Number.isSafeInteger(value)) throw new RangeError("Invalid integer");
      return String(value);
    }
  });
  bank.register<boolean>("boolean", {
    decode(text) {
      if (text.toLowerCase() === "true") return true;
      if (text.toLowerCase() === "false") return false;
      throw new RangeError("Invalid boolean");
    },
    encode(value) {
      if (typeof value !== "boolean") throw new RangeError("Invalid boolean");
      return String(value);
    }
  });
  bank.register<string[]>("string-list", {
    decode(text) {
      let value: unknown;
      try { value = JSON.parse(text); } catch { throw new RangeError("Invalid string list"); }
      if (!Array.isArray(value) || !value.every((item) => typeof item === "string")) {
        throw new RangeError("Invalid string list");
      }
      return [...value];
    },
    encode(value) {
      if (!Array.isArray(value) || !value.every((item) => typeof item === "string")) {
        throw new RangeError("Invalid string list");
