import { CodecBank, createStandardCodecBank } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: ${JSON.stringify(actual)}`);
}
function throws(fn: () => unknown, ctor: new (...args: any[]) => Error, message: string): void {
  let caught: unknown;
  try { fn(); } catch (error) { caught = error; }
  assert(caught instanceof ctor, message);
}

const custom = new CodecBank();
custom.register("Exact", { decode: (text) => text.length, encode: (value: number) => String(value) });
custom.register("lower", { decode: (text) => text, encode: (value: string) => value });
deepEqual(custom.names(), ["Exact", "lower"], "names preserve registration order and case");
const exposedNames = custom.names();
exposedNames.reverse();
deepEqual(custom.names(), ["Exact", "lower"], "names returns a copy");
throws(() => custom.register(" \t", { decode: (text) => text, encode: (value: string) => value }), RangeError, "blank name rejected");
throws(() => custom.register("Exact", { decode: (text) => text, encode: (value: string) => value }), Error, "duplicate rejected");
deepEqual(custom.names(), ["Exact", "lower"], "failed registrations preserve bank");
assert(custom.decode<number>("Exact", "abcd") === 4, "custom decode");
assert(custom.encode<number>("Exact", 12) === "12", "custom encode");
throws(() => custom.decode("exact", "x"), Error, "names are case-sensitive");
throws(() => custom.encode("missing", "x"), Error, "unknown encode rejected");

const bank = createStandardCodecBank();
deepEqual(bank.names(), ["integer", "boolean", "string-list"], "standard codec order");
for (const text of ["0", "-0", "42", "-17", String(Number.MAX_SAFE_INTEGER), String(Number.MIN_SAFE_INTEGER)]) {
  const decoded = bank.decode<number>("integer", text);
  assert(Object.is(decoded, Number(text)), `integer decode ${text}`);
}
for (const text of ["", "+1", "01", "-01", "1.0", " 1", "1 ", "1e2", String(Number.MAX_SAFE_INTEGER + 1)]) {
  throws(() => bank.decode<number>("integer", text), RangeError, `invalid integer ${text}`);
}
assert(bank.encode<number>("integer", 0) === "0", "encode zero");
assert(bank.encode<number>("integer", Number.MIN_SAFE_INTEGER) === String(Number.MIN_SAFE_INTEGER), "encode safe boundary");
for (const value of [1.5, Infinity, Number.NaN, Number.MAX_SAFE_INTEGER + 1]) {
  throws(() => bank.encode<number>("integer", value), RangeError, "invalid integer encode");
}

assert(bank.decode<boolean>("boolean", "true") === true, "decode true");
assert(bank.decode<boolean>("boolean", "false") === false, "decode false");
assert(bank.encode<boolean>("boolean", true) === "true", "encode true");
assert(bank.encode<boolean>("boolean", false) === "false", "encode false");
for (const value of ["True", "FALSE", "0", ""] as const) {
  throws(() => bank.decode<boolean>("boolean", value), RangeError, "invalid boolean decode");
}
throws(() => bank.encode<boolean>("boolean", "true" as unknown as boolean), RangeError, "runtime non-boolean rejected");

const decoded = bank.decode<string[]>("string-list", "[\"a\",\"b\",\"a\"]");
deepEqual(decoded, ["a", "b", "a"], "string-list decode");
decoded[0] = "changed";
deepEqual(bank.decode<string[]>("string-list", "[\"a\",\"b\",\"a\"]"), ["a", "b", "a"], "decoded arrays are independent");
const supplied = ["x", "y"];
assert(bank.encode<string[]>("string-list", supplied) === "[\"x\",\"y\"]", "string-list encode");
deepEqual(supplied, ["x", "y"], "encode does not mutate array");
for (const text of ["not json", "{}", "[1]", "[\"x\",null]"]) {
  throws(() => bank.decode<string[]>("string-list", text), RangeError, "invalid string-list decode");
}
for (const value of [{}, ["x", 1], "x"] as unknown[]) {
  throws(() => bank.encode<string[]>("string-list", value as string[]), RangeError, "invalid string-list encode");
}

